import 'package:flutter/material.dart';class AnimatedCounter3D extends StatelessWidget{final double value;final String suffix;final TextStyle? style;const AnimatedCounter3D({super.key,required this.value,this.suffix='',this.style});@override Widget build(BuildContext c)=>TweenAnimationBuilder<double>(tween:Tween(begin:0,end:value),duration:const Duration(milliseconds:900),curve:Curves.easeOutCubic,builder:(c,v,_){return Transform(transform:Matrix4.identity()..setEntry(3,2,.001)..rotateX(.02),alignment:Alignment.center,child:Text(v.round().toString()+suffix,style:style));});}